from pathlib import Path
import json,hashlib,importlib.util,sys,array
P=Path(__file__).resolve().parent.parent;ROOT=P.parent.parent;D=ROOT/'.porting-state/diagnostics/cm';spec=importlib.util.spec_from_file_location('independent_oracle',P/'generate_assets.py');o=importlib.util.module_from_spec(spec);spec.loader.exec_module(o)
